# Full emulator of the VM at 0x12b0, recording eax ("acc") after each handler
data = bytes.fromhex('***REDACTED-HEX***')
key  = bytes.fromhex('8ddeb90f')
bytecode1 = bytes.fromhex('***REDACTED-HEX***')
bytecode2 = bytes.fromhex('***REDACTED-HEX***')

# handler addresses
H = {0:0x13e0,1:0x13c0,3:0x13a0,4:0x1390,5:0x1370,6:0x1320,7:0x1320,8:0x13f8,9:0x133a,10:0x1350}

def run(bc, name, trace=True):
    ip = 0
    r14 = 0
    ebp = 0x186a0
    out = []
    steps = 0
    while True:
        steps += 1
        if steps > 10000:
            print("  [LOOP LIMIT]"); break
        op = bc[ip]
        if trace:
            print(f"  ip={ip} op=0x{op:02x} r14={r14}", end='')
        # dispatch
        if op == 0xc3:
            # 0x1320
            if ip+1 == 10:
                if trace: print(" -> EXIT(operand oob)")
                break
            operand = bc[ip+1]
            acc = operand
            ip += 2
            if trace: print(f" -> 0x1320 loadimm acc=0x{operand:02x} ip={ip}")
        else:
            idx = (op + 0x3f) & 0xff
            if idx > 0xa:
                # default 0x13f8: no-op
                ip += 1
                if trace: print(f" -> default nop ip={ip}")
            else:
                h = H[idx]
                if h == 0x13e0:
                    acc = key[r14 & 3]
                    ip += 1
                    if trace: print(f" -> loadkey acc=0x{acc:02x} ip={ip}")
                elif h == 0x13c0:
                    acc = data[r14] if r14 <= 30 else None
                    ip += 1
                    if trace: print(f" -> loaddata acc=0x{acc:02x} ip={ip}")
                elif h == 0x13a0:
                    # jump: ip = operand ^ 0xc3
                    if ip+1 == 10:
                        if trace: print(" -> EXIT(jump oob)"); break
                    operand = bc[ip+1]
                    ip = operand ^ 0xc3
                    if trace: print(f" -> jump operand=0x{operand:02x} ip={ip}")
                elif h == 0x1390:
                    r14 += 1
                    ip += 1
                    if trace: print(f" -> incr r14 ip={ip}")
                elif h == 0x1370:
                    out.append('.')
                    ip += 1
                    if trace: print(f" -> putc('.') ip={ip}")
                elif h == 0x1320:
                    if ip+1 == 10:
                        if trace: print(" -> EXIT(operand oob)"); break
                    operand = bc[ip+1]
                    acc = operand
                    ip += 2
                    if trace: print(f" -> loadimm acc=0x{operand:02x} ip={ip}")
                elif h == 0x133a:
                    if trace: print(" -> EXIT")
                    break
                elif h == 0x1350:
                    # conditional: if ip+1==10 exit; else ip+=2; acc=operand^0xc3; if r14!=31: ip=acc
                    if ip+1 == 10:
                        if trace: print(" -> EXIT(condjmp oob)"); break
                    operand = bc[ip+1]
                    tgt = operand ^ 0xc3
                    ip += 2
                    if r14 != 31:
                        ip = tgt
                    if trace: print(f" -> condjmp operand=0x{operand:02x} tgt={tgt} r14==31?{r14==31} ip={ip}")
                else:
                    raise Exception(f"unknown h {h:x}")
        ebp -= 1
        if ebp == 0:
            if trace: print("  [ebp exhausted]")
            break
        if ip >= len(bc):
            if trace: print("  [ip out of range]")
            break
    print(f"  OUTPUT ({name}): {''.join(out)}  (len={len(out)}, steps={steps}, final r14={r14})")

print("=== DECOY bytecode 0x4010 ===")
run(bytecode1, "decoy")
print()
print("=== SECOND bytecode 0x4040 ===")
run(bytecode2, "second")
EOF

