import itertools
data = bytes.fromhex('***REDACTED-HEX***')
key = bytes.fromhex('8ddeb90f')
seed = int.from_bytes(key, 'little')  # 0x0fb9de8d
seed_be = int.from_bytes(key, 'big')  # 0x8ddeb90f

def printable(s):
    return sum(1 for c in s if 32<=c<127)

def try_keystream(name, ks):
    # ks: list of bytes length >= 31
    for opn,op in [('xor',lambda a,b:(a^b)&0xff),('add',lambda a,b:(a+b)&0xff),('sub',lambda a,b:(a-b)&0xff),('rsub',lambda a,b:(b-a)&0xff)]:
        out = bytes(op(data[i], ks[i]) for i in range(31))
        s=''.join(chr(c) if 32<=c<127 else '.' for c in out)
        if printable(s)>=25 or 'flag' in s.lower():
            print(f"{name} {opn}: {s}")
        # also try printing first few always
    # just print xor variant for inspection of best
    out = bytes(data[i]^ks[i] for i in range(31))
    s=''.join(chr(c) if 32<=c<127 else '.' for c in out)
    return printable(s), s

results=[]
# xorshift32 variants
for name, gen in []:
    pass

def xorshift32(seed, a,b,c):
    st = seed & 0xffffffff
    ks=[]
    for _ in range(31):
        st ^= (st << a) & 0xffffffff
        st ^= (st >> b) & 0xffffffff
        st ^= (st << c) & 0xffffffff
        st &= 0xffffffff
        ks.append(st & 0xff)
    return ks

for a,b,c in [(13,17,5),(13,7,17),(5,17,13),(11,19,8),(1,3,10)]:
    for sname, sd in [('le',seed),('be',seed_be)]:
        ks = xorshift32(sd,a,b,c)
        sc,s = try_keystream(f"xorshift({a},{b},{c}) {sname}", ks)
        if sc>=20: results.append((sc,f"xorshift({a},{b},{c}) {sname} xor", s))

# LCG variants (glibc, ANSI, common)
def lcg(seed, a, c):
    st = seed & 0xffffffff
    ks=[]
    for _ in range(31):
        st = (st*a + c) & 0xffffffff
        ks.append((st >> 16) & 0xff)  # high bits like rand()
        # also low byte variant
    return ks

for a,c in [(1103515245,12345),(214013,2531011),(1664525,1013904223),(22695477,1),(134775813,1)]:
    for sname, sd in [('le',seed),('be',seed_be)]:
        for part in ['hi','lo']:
            st = sd & 0xffffffff
            ks=[]
            for _ in range(31):
                st = (st*a + c) & 0xffffffff
                ks.append((st>>16)&0xff if part=='hi' else st&0xff)
            sc,s = try_keystream(f"lcg({a},{c}) {sname} {part}", ks)
            if sc>=20: results.append((sc,f"lcg {sname} {part}", s))

for r in sorted(results, reverse=True):
    print(r)
print("done")
